import type { PlaybackDatabase } from "./play-counts";

export const PLAY_REQUESTS_PER_MINUTE = 30;
export const PLAY_DUPLICATE_SECONDS = 600;
export const PLAY_GUARD_RETENTION_SECONDS = 48 * 60 * 60;
export type PlayOutcome = "accepted" | "duplicate" | "rate-limit";

// One INSERT checks the shared quota and classifies duplicates atomically.
// Duplicate attempts consume the minute allowance but never extend the last
// accepted play's ten-minute window. Request IDs are generated by the server.
const RESERVE = `INSERT INTO play_attempts
  (request_id, ip_key, video_key, created_at, accepted)
SELECT ?1, ?2, ?3, ?4, CASE WHEN
  EXISTS (SELECT 1 FROM play_events WHERE event_id = ?6)
  OR EXISTS (SELECT 1 FROM play_attempts
    WHERE video_key = ?3 AND accepted = 1 AND created_at > ?4 - ?8)
  THEN 0 ELSE 1 END
WHERE (SELECT COUNT(*) FROM play_attempts WHERE ip_key = ?2 AND created_at >= ?5) < ?7`;
const INSERT = `INSERT INTO play_events (event_id, video_id, played_at)
SELECT ?1, ?2, ?3 WHERE EXISTS (
  SELECT 1 FROM play_attempts WHERE request_id = ?4 AND accepted = 1
)`;
const OUTCOME = `SELECT CASE
WHEN EXISTS (SELECT 1 FROM play_attempts WHERE request_id = ? AND accepted = 1) THEN 'accepted'
WHEN EXISTS (SELECT 1 FROM play_attempts WHERE request_id = ?) THEN 'duplicate'
ELSE 'rate-limit' END AS reason`;

/** Shared D1 transaction, independent of edge-instance memory. Each Taiwan day
 * has distinct, domain-separated IP and IP/video HMACs; no cross-site identity.
 * Expired guard rows are removed on the next eligible write (as for contributions).
 */
export async function guardAndRecordPlay(
  db: PlaybackDatabase | undefined,
  ip: string,
  eventId: string,
  videoId: string,
  now: number,
  expiredPlaysCutoff: number,
): Promise<PlayOutcome> {
  if (!db || !ip) throw new Error("play-guard-unavailable");
  const { results } = await db
    .prepare("SELECT secret FROM play_guard_key WHERE id = 1")
    .all<{ secret: string }>();
  const secret = results[0]?.secret;
  if (!secret || !/^[0-9a-f]{64}$/.test(secret))
    throw new Error("play-guard-unavailable");
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const hash = async (domain: string, values: (string | number)[]) => {
    const signature = await crypto.subtle.sign(
      "HMAC",
      key,
      new TextEncoder().encode(JSON.stringify([domain, ...values])),
    );
    return Array.from(new Uint8Array(signature), (byte) =>
      byte.toString(16).padStart(2, "0"),
    ).join("");
  };
  const day = Math.floor((now + 28800) / 86400);
  const [ipKey, videoKey] = await Promise.all([
    hash("atlas-play-ip-v1", [day, ip]),
    hash("atlas-play-video-v1", [day, ip, videoId]),
  ]);
  const id = crypto.randomUUID();
  // D1 batch is transactional; like the contribution guard, a final SELECT
  // observes this reservation inside the transaction, without metadata guesses.
  const batch = await db.batch([
    db
      .prepare("DELETE FROM play_attempts WHERE created_at <= ?")
      .bind(now - PLAY_GUARD_RETENTION_SECONDS),
    db
      .prepare("DELETE FROM play_events WHERE played_at <= ?")
      .bind(expiredPlaysCutoff),
    db
      .prepare(RESERVE)
      .bind(
        id,
        ipKey,
        videoKey,
        now,
        Math.floor(now / 60) * 60,
        eventId,
        PLAY_REQUESTS_PER_MINUTE,
        PLAY_DUPLICATE_SECONDS,
      ),
    db.prepare(INSERT).bind(eventId, videoId, now, id),
    db.prepare(OUTCOME).bind(id, id),
  ]);
  const result = batch[4]?.results[0] as { reason?: string } | undefined;
  if (
    !result ||
    !["accepted", "duplicate", "rate-limit"].includes(result.reason ?? "")
  )
    throw new Error("play-guard-unavailable");
  return result.reason as PlayOutcome;
}
